import{I as p,o as t,c as r,b6 as e,J as o,w as d,j as i,a as l}from"./chunks/framework.COUcLbTA.js";const u=JSON.parse('{"title":"双钻模型：先做对的事，再把事做对","description":"面向零基础读者的 Double Diamond 入门文章。理解 Discover、Define、Develop、Deliver 四个阶段，避免在问题还没搞清楚时就急着做原型。","frontmatter":{"title":"双钻模型：先做对的事，再把事做对","description":"面向零基础读者的 Double Diamond 入门文章。理解 Discover、Define、Develop、Deliver 四个阶段，避免在问题还没搞清楚时就急着做原型。"},"headers":[],"relativePath":"zh-cn/stage-1/appendix-double-diamond/index.md","filePath":"zh-cn/stage-1/appendix-double-diamond/index.md"}'),h={name:"zh-cn/stage-1/appendix-double-diamond/index.md"},k=Object.assign(h,{setup(c){const s="约 <strong>1.5 小时</strong>";return(g,a)=>{const n=p("ChapterIntroduction");return t(),r("div",null,[a[1]||(a[1]=e('<h1 id="双钻模型-先做对的事-再把事做对" tabindex="-1">双钻模型：先做对的事，再把事做对 <a class="header-anchor" href="#双钻模型-先做对的事-再把事做对" aria-label="Permalink to “双钻模型：先做对的事，再把事做对”">​</a></h1><p><a id="top-dd"></a></p><h2 id="本章导读" tabindex="-1">本章导读 <a class="header-anchor" href="#本章导读" aria-label="Permalink to “本章导读”">​</a></h2>',3)),o(n,{duration:s,tags:["Double Diamond","设计思维","需求分析","方案设计"],coreOutput:"1 个更清楚的问题定义和 1 个更合理的验证切口",expectedOutput:"不再一上来就急着画原型，而是知道先想清楚问题，再比较方案"},{default:d(()=>[...a[0]||(a[0]=[i("p",null,"很多人第一次做产品时，最容易踩的坑不是“不够努力”，而是太快进入解决方案。",-1),i("p",null,"脑子里刚冒出一个方向，就开始想页面怎么画、按钮放哪、要不要接 AI、要不要做登录注册、原型用什么工具画。忙了一圈之后，才发现最根本的问题根本没想清楚：用户到底是不是真的有这个痛点？这个问题值不值得现在解决？你以为自己在推进项目，其实只是很努力地在错误方向上加速。",-1),i("p",null,"双钻模型（Double Diamond）就是用来避免这种情况的。",-1),i("p",null,[l("它最有价值的提醒是："),i("strong",null,"“做对的事情”和“把事情做对”，是两个完全不同的阶段。"),l(" 如果你还没搞清楚问题，就急着冲去做原型，通常只会把错误方向做得更完整。")],-1)])]),_:1}),a[2]||(a[2]=e(`<div class="info custom-block"><p class="custom-block-title">最小 SOP</p><p><strong>目的</strong>：看完后，你会更清楚做产品时什么时候该先想问题，什么时候才该开始想方案和原型，避免一上来就在错误方向上做得很认真。</p><p><strong>行动项</strong>：按 <code>Discover → Define → Develop → Deliver</code> 四步往下走，每一步只做当前阶段该做的事。</p><p><strong>结果</strong>：你会得到一个更清楚的问题定义、几种可比较的方案，以及一个可验证的最小版本。</p><p><strong>关键词跳转</strong>：<a href="#dd-what">双钻模型是什么</a> · <a href="#dd-first">第一个钻石</a> · <a href="#dd-ai">AI 怎么帮你</a></p></div><h2 id="你将学到以下内容" tabindex="-1">你将学到以下内容 <a class="header-anchor" href="#你将学到以下内容" aria-label="Permalink to “你将学到以下内容”">​</a></h2><ol><li>双钻模型是什么，为什么它适合零基础做产品时使用</li><li>Discover、Define、Develop、Deliver 四个阶段分别在做什么</li><li>怎样区分“现在应该继续发散”还是“现在应该开始收敛”</li><li>如何把双钻模型用在 AI 产品、原型设计和需求验证里</li></ol><p><a id="dd-what"></a></p><h2 id="_1-双钻模型到底是什么" tabindex="-1"><a href="#top-dd">1. 双钻模型到底是什么</a> <a class="header-anchor" href="#_1-双钻模型到底是什么" aria-label="Permalink to “1. 双钻模型到底是什么”">​</a></h2><p>双钻模型是英国 <strong>Design Council</strong> 推广的一套经典设计流程框架。它把一个完整的设计与创新过程，画成两个连续的钻石形状。</p><p>之所以是“钻石”，是因为每个钻石都包含两种相反但都很重要的动作：</p><ul><li><strong>发散</strong>：先把视野打开，看更多可能性</li><li><strong>收敛</strong>：再把范围缩小，做出判断和取舍</li></ul><p>整个过程一共四步：</p><ol><li><strong>Discover</strong>：广泛了解用户、问题、环境和市场</li><li><strong>Define</strong>：从大量信息里提炼出真正值得解决的核心问题</li><li><strong>Develop</strong>：围绕核心问题发散多种解决方案</li><li><strong>Deliver</strong>：筛选、原型、测试并交付更合适的方案</li></ol><p>如果把这四步压缩成一句最容易记住的话，就是：</p><ul><li><strong>第一个钻石</strong>：先搞清楚到底要解决什么问题</li><li><strong>第二个钻石</strong>：再决定用什么方案去解决它</li></ul><p>这也是你刚才说得很准确的那句话：</p><ul><li><strong>第一个钻石：做对的事情</strong></li><li><strong>第二个钻石：把事情做对</strong></li></ul><h2 id="_2-为什么双钻模型特别适合新手" tabindex="-1">2. 为什么双钻模型特别适合新手 <a class="header-anchor" href="#_2-为什么双钻模型特别适合新手" aria-label="Permalink to “2. 为什么双钻模型特别适合新手”">​</a></h2><p>新手做产品最常见的节奏，往往是这样的：</p><ul><li>想到一个点子</li><li>觉得这个方向很酷</li><li>马上开始画原型</li><li>做着做着发现功能越来越多</li><li>最后不知道自己到底在解决什么问题</li></ul><p>双钻模型的价值，不在于让流程变复杂，而在于 <strong>强迫你把“理解问题”和“设计方案”拆开</strong> 。</p><p>这件事听起来很普通，但实际非常重要。因为很多失败的产品，不是执行不认真，而是：</p><ul><li>选错了问题</li><li>误解了用户</li><li>过早锁定了解决方案</li><li>把大量时间花在细节打磨上，却没有验证方向</li></ul><p>双钻模型就是在不断提醒你：</p><ul><li>不要因为想法顺手，就默认问题已经成立</li><li>不要因为方案能做出来，就默认它值得做</li><li>不要因为原型看起来完整，就默认用户会真的需要</li></ul><p><a id="dd-first"></a></p><h2 id="_3-第一个钻石-做对的事情" tabindex="-1"><a href="#top-dd">3. 第一个钻石：做对的事情</a> <a class="header-anchor" href="#_3-第一个钻石-做对的事情" aria-label="Permalink to “3. 第一个钻石：做对的事情”">​</a></h2><p>第一个钻石关注的是 <strong>问题本身</strong> ，而不是解决方案。</p><p>你可以把它理解成一句话：<strong>先别急着做，先搞清楚到底值不值得做。</strong></p><h3 id="_3-1-discover-先把问题空间打开" tabindex="-1">3.1 Discover：先把问题空间打开 <a class="header-anchor" href="#_3-1-discover-先把问题空间打开" aria-label="Permalink to “3.1 Discover：先把问题空间打开”">​</a></h3><p>Discover 阶段的核心任务，是 <strong>广泛调研，而不是快速下结论。</strong></p><p>这一步通常会做的事情包括：</p><ul><li>看用户在真实场景里怎么做</li><li>访谈潜在用户，了解他们最近一次遇到问题是什么时候</li><li>观察他们现在怎么凑合解决</li><li>看竞品和替代方案都在怎么处理</li><li>收集市场、流程、约束、上下游信息</li></ul><p>很多人会误以为 Discover 就是“多看点资料”。其实更关键的是：<strong>你要理解人和场景，而不只是搜一堆信息。</strong></p><p>比如你想做一个“AI 帮忙整理会议纪要”的工具，在 Discover 阶段更应该关注的是：</p><ul><li>用户开完会后到底哪里最痛苦</li><li>是记录难，还是整理难，还是同步难</li><li>他们现在是自己写、让实习生写、录音回听，还是干脆不整理</li><li>哪些会议场景最需要纪要，哪些根本不需要</li></ul><p>这一步最重要的目标不是得出答案，而是 <strong>别太早以为自己已经知道答案。</strong></p><h3 id="_3-2-define-从一堆信息里提炼出核心问题" tabindex="-1">3.2 Define：从一堆信息里提炼出核心问题 <a class="header-anchor" href="#_3-2-define-从一堆信息里提炼出核心问题" aria-label="Permalink to “3.2 Define：从一堆信息里提炼出核心问题”">​</a></h3><p>如果 Discover 是打开视野，Define 就是开始收束。</p><p>Define 阶段要做的，不是把所有观察都保留下来，而是问：</p><ul><li>真正最值得优先解决的问题是哪一个</li><li>哪个问题最常出现、最痛、最有价值</li><li>我们第一版到底只盯住哪一个场景</li></ul><p>这一步的核心，是把一个宽泛话题，收敛成一个清晰问题定义。</p><p>比如你一开始说：</p><blockquote><p>我想做一个提高开会效率的 AI 工具。</p></blockquote><p>到了 Define 阶段，更好的表达可能会变成：</p><blockquote><p>我们先解决项目型团队在 30 到 60 分钟协作会议结束后，无法在 10 分钟内输出带待办、责任人和截止时间的纪要这个问题。</p></blockquote><p>这时候问题就开始变清楚了：</p><ul><li>用户是谁</li><li>场景是什么</li><li>卡点是什么</li><li>成功标准是什么</li></ul><p>Define 的本质，就是 <strong>从“问题很多”收敛到“这次先解决哪一个问题”。</strong></p><h2 id="_4-第二个钻石-把事情做对" tabindex="-1">4. 第二个钻石：把事情做对 <a class="header-anchor" href="#_4-第二个钻石-把事情做对" aria-label="Permalink to “4. 第二个钻石：把事情做对”">​</a></h2><p>当你完成第一个钻石后，才真正适合进入第二个钻石。因为这时你解决的不是一个模糊方向，而是一个被收敛过的具体问题。</p><h3 id="_4-1-develop-围绕核心问题发散方案" tabindex="-1">4.1 Develop：围绕核心问题发散方案 <a class="header-anchor" href="#_4-1-develop-围绕核心问题发散方案" aria-label="Permalink to “4.1 Develop：围绕核心问题发散方案”">​</a></h3><p>Develop 阶段的重点，是 <strong>围绕同一个问题，探索多种可能方案。</strong></p><p>注意，这里的发散和 Discover 阶段不一样。</p><ul><li>Discover 的发散，是在探索问题空间</li><li>Develop 的发散，是在探索解决方案空间</li></ul><p>比如还是会议纪要这个例子，到了 Develop 阶段，你可以开始想：</p><ul><li>是做网页工具，还是会议插件</li><li>是上传录音后处理，还是实时记录</li><li>是只做摘要，还是重点做待办提取</li><li>是强调个人效率，还是强调团队同步</li><li>是给用户自由编辑，还是直接输出结构化模板</li></ul><p>这一步很适合脑暴，也很适合和团队一起把方案拉开。</p><p>但这里有一个前提：<strong>所有方案都必须服务同一个已定义的问题。</strong><br> 如果问题没定义清楚，Develop 很容易又重新变成功能乱飞。</p><h3 id="_4-2-deliver-选择方案、做原型、测试和交付" tabindex="-1">4.2 Deliver：选择方案、做原型、测试和交付 <a class="header-anchor" href="#_4-2-deliver-选择方案、做原型、测试和交付" aria-label="Permalink to “4.2 Deliver：选择方案、做原型、测试和交付”">​</a></h3><p>Deliver 阶段是第二个钻石里的收敛阶段。</p><p>这时你要做的不是继续想更多，而是开始判断：</p><ul><li>哪个方案最适合当前阶段</li><li>哪个版本最小但最有用</li><li>哪些功能必须先做，哪些可以以后再说</li><li>怎么做原型、测试和小范围验证</li></ul><p>很多人以为 Deliver 就等于“上线”。其实它更准确的意思是：<strong>把一个方案变成可测试、可验证、可迭代的东西。</strong></p><p>它可能是：</p><ul><li>一张低保真流程图</li><li>一个 Figma 原型</li><li>一个可运行的 MVP</li><li>一次小规模用户测试</li><li>一轮真实反馈后的迭代版本</li></ul><p>Deliver 的重点不是“完美交付”，而是 <strong>尽快把方案放进真实环境里验证。</strong></p><h2 id="_5-一个最容易记住的对照表" tabindex="-1">5. 一个最容易记住的对照表 <a class="header-anchor" href="#_5-一个最容易记住的对照表" aria-label="Permalink to “5. 一个最容易记住的对照表”">​</a></h2><p>如果你总是分不清四个阶段，可以直接记下面这个版本：</p><table tabindex="0"><thead><tr><th>阶段</th><th>你在做什么</th><th>关键词</th><th>常见产出</th></tr></thead><tbody><tr><td>Discover</td><td>理解问题</td><td>调研、观察、访谈、收集信息</td><td>用户洞察、场景笔记、问题清单</td></tr><tr><td>Define</td><td>定义问题</td><td>提炼、聚焦、取舍、重写问题</td><td>问题定义、优先级、MVP 切口</td></tr><tr><td>Develop</td><td>探索方案</td><td>脑暴、比较、共创、原型设想</td><td>方案列表、流程草图、原型方向</td></tr><tr><td>Deliver</td><td>验证方案</td><td>原型、测试、迭代、交付</td><td>原型、测试反馈、优化版本</td></tr></tbody></table><p>再压缩一点，就是这样：</p><ul><li><strong>Discover / Define</strong>：解决“做对的事情”</li><li><strong>Develop / Deliver</strong>：解决“把事情做对”</li></ul><h2 id="_6-双钻模型最常见的误区" tabindex="-1">6. 双钻模型最常见的误区 <a class="header-anchor" href="#_6-双钻模型最常见的误区" aria-label="Permalink to “6. 双钻模型最常见的误区”">​</a></h2><h3 id="_6-1-还没-discover-就直接-deliver" tabindex="-1">6.1 还没 Discover，就直接 Deliver <a class="header-anchor" href="#_6-1-还没-discover-就直接-deliver" aria-label="Permalink to “6.1 还没 Discover，就直接 Deliver”">​</a></h3><p>这是最常见的一种。很多人刚有想法就开画原型、写 PRD、接模型、做页面。</p><p>问题不是你做得不认真，而是你可能根本还没确认问题值不值得解决。</p><h3 id="_6-2-discover-很久-但始终不-define" tabindex="-1">6.2 Discover 很久，但始终不 Define <a class="header-anchor" href="#_6-2-discover-很久-但始终不-define" aria-label="Permalink to “6.2 Discover 很久，但始终不 Define”">​</a></h3><p>另一种极端是一直调研、一直看资料、一直访谈，却迟迟不敢收敛。</p><p>双钻不是让你无限发散，而是提醒你：发散之后必须进入判断和取舍。</p><h3 id="_6-3-define-之后-又偷偷改问题" tabindex="-1">6.3 Define 之后，又偷偷改问题 <a class="header-anchor" href="#_6-3-define-之后-又偷偷改问题" aria-label="Permalink to “6.3 Define 之后，又偷偷改问题”">​</a></h3><p>很多团队会在 Develop 时因为某个方案更容易做，就反过来修改问题定义，让它适配现有方案。</p><p>这很危险。因为你可能不是在解决问题，而是在为自己偏爱的方案找理由。</p><h3 id="_6-4-把-deliver-误解成-大而全上线" tabindex="-1">6.4 把 Deliver 误解成“大而全上线” <a class="header-anchor" href="#_6-4-把-deliver-误解成-大而全上线" aria-label="Permalink to “6.4 把 Deliver 误解成“大而全上线””">​</a></h3><p>Deliver 不是说必须把完整产品都做完才算结束。很多时候，一个可以测试的原型、一轮真实用户试用，已经是很好的 deliver。</p><h2 id="_7-在-ai-产品里-双钻模型怎么用" tabindex="-1">7. 在 AI 产品里，双钻模型怎么用 <a class="header-anchor" href="#_7-在-ai-产品里-双钻模型怎么用" aria-label="Permalink to “7. 在 AI 产品里，双钻模型怎么用”">​</a></h2><p>AI 产品特别容易掉进“能力先行”的坑里，因为模型能力看起来太诱人了。你会很想直接去想：</p><ul><li>要不要接多模态</li><li>要不要做 Agent</li><li>要不要加工作流</li><li>要不要接语音、图像、联网搜索</li></ul><p>但双钻模型会逼你先问：</p><ul><li>用户到底在哪个环节真的卡住了</li><li>这个卡点是不是非 AI 不可</li><li>如果不用 AI，现有办法到底哪里最差</li><li>AI 加进去之后，最核心的进展是什么</li></ul><p>这能帮你避免一种常见情况：<strong>能力很强，价值很弱。</strong></p><p>一个实用的顺序是：</p><ol><li>在 Discover 阶段观察用户现在怎么处理任务</li><li>在 Define 阶段把最痛的一个场景写成一句清晰的问题定义</li><li>在 Develop 阶段再去比较哪些 AI 能力最适合服务这个问题</li><li>在 Deliver 阶段做一个最小版本，让真实用户测试</li></ol><h2 id="_8-可以直接套用的双钻模板" tabindex="-1">8. 可以直接套用的双钻模板 <a class="header-anchor" href="#_8-可以直接套用的双钻模板" aria-label="Permalink to “8. 可以直接套用的双钻模板”">​</a></h2><p>如果你正在做自己的产品，可以先按这个顺序往下写：</p><h3 id="discover" tabindex="-1">Discover <a class="header-anchor" href="#discover" aria-label="Permalink to “Discover”">​</a></h3><ul><li>我观察到的用户是谁？</li><li>他们最近一次遇到这个问题是什么时候？</li><li>他们现在怎么解决？</li><li>他们最烦、最慢、最不放心的地方是什么？</li></ul><h3 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to “Define”">​</a></h3><ul><li>这堆问题里，最值得优先解决的是哪一个？</li><li>哪个场景最高频，或者最关键？</li><li>我们第一版先只服务谁、只解决什么？</li><li>成功解决后，用户状态会发生什么变化？</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li>针对这个问题，有哪些可能方案？</li><li>哪些方案最轻、最快、最容易验证？</li><li>哪些是必须做，哪些是以后再说？</li></ul><h3 id="deliver" tabindex="-1">Deliver <a class="header-anchor" href="#deliver" aria-label="Permalink to “Deliver”">​</a></h3><ul><li>我们最小可以交付什么来验证这个方向？</li><li>是流程图、原型，还是 MVP？</li><li>需要找谁测试？</li><li>测试后怎样判断要继续、修改还是放弃？</li></ul><h2 id="_9-一个从零基础也能看懂的例子" tabindex="-1">9. 一个从零基础也能看懂的例子 <a class="header-anchor" href="#_9-一个从零基础也能看懂的例子" aria-label="Permalink to “9. 一个从零基础也能看懂的例子”">​</a></h2><p>假设你想做一个“帮大学生准备求职简历”的 AI 工具。</p><p>很多人一开始就会直接进入第二个钻石，开始想：</p><ul><li>要不要一键美化</li><li>要不要智能改写</li><li>要不要自动匹配 JD</li><li>要不要生成自我介绍</li></ul><p>但按双钻模型，更好的过程会是这样：</p><h3 id="第一个钻石" tabindex="-1">第一个钻石 <a class="header-anchor" href="#第一个钻石" aria-label="Permalink to “第一个钻石”">​</a></h3><p><strong>Discover</strong></p><ul><li>去聊应届生最近一次改简历是什么时候</li><li>看他们怎么从旧简历改成新版本</li><li>了解他们最困扰的是“不会写”“不会改”，还是“不会判断好不好”</li></ul><p><strong>Define</strong></p><ul><li>最后收敛出一个更具体的问题：</li><li>不是“大学生不会做简历”</li><li>而是“第一次投递实习的学生，很难把已有经历改写成贴合岗位的表达，因此拖延投递”</li></ul><h3 id="第二个钻石" tabindex="-1">第二个钻石 <a class="header-anchor" href="#第二个钻石" aria-label="Permalink to “第二个钻石”">​</a></h3><p><strong>Develop</strong></p><ul><li>想几种方案：模板库、AI 改写、岗位对照、简历评分、案例参考</li></ul><p><strong>Deliver</strong></p><ul><li>第一版只做“根据岗位描述改写经历 bullet points”</li><li>给 5 个学生试用，看他们会不会更快投出第一版简历</li></ul><p>你会发现，一旦第一个钻石做扎实，第二个钻石会清楚很多。</p><h2 id="_10-小结" tabindex="-1">10. 小结 <a class="header-anchor" href="#_10-小结" aria-label="Permalink to “10. 小结”">​</a></h2><p>双钻模型最有力量的地方，是它帮你把一整团混乱拆成了四个更清楚的动作：</p><ul><li>先发散理解问题</li><li>再收敛定义问题</li><li>再发散探索方案</li><li>最后收敛交付方案</li></ul><p>它不是让你变慢，而是让你 <strong>少走很多看起来很忙、其实方向不对的弯路。</strong></p><p>尤其在 AI 时代，做东西变得越来越快，双钻模型反而更重要。因为当“做出来”越来越容易时，真正稀缺的能力会变成：<strong>你有没有在解决一个值得解决的问题，以及你有没有用合适的方式去解决它。</strong></p><p>记住这一句就够了：</p><p><strong>先做对的事情，再把事情做对。</strong></p><p><a id="dd-ai"></a></p><h2 id="_11-如何利用-ai-帮你跑双钻流程" tabindex="-1"><a href="#top-dd">11. 如何利用 AI 帮你跑双钻流程</a> <a class="header-anchor" href="#_11-如何利用-ai-帮你跑双钻流程" aria-label="Permalink to “11. 如何利用 AI 帮你跑双钻流程”">​</a></h2><p>双钻模型本身不是 AI 工具，但 AI 很适合在四个阶段里充当“加速器”。关键不是让 AI 替你决策，而是让它帮你扩展视野、整理信息、比较方案和生成验证材料。</p><h3 id="_11-1-在-discover-阶段-用-ai-先做一轮信息铺垫" tabindex="-1">11.1 在 Discover 阶段，用 AI 先做一轮信息铺垫 <a class="header-anchor" href="#_11-1-在-discover-阶段-用-ai-先做一轮信息铺垫" aria-label="Permalink to “11.1 在 Discover 阶段，用 AI 先做一轮信息铺垫”">​</a></h3><p>在正式访谈和调研前，你可以先让 AI 帮你做一些轻量级问题扫描，比如：</p><ul><li>市面上常见替代方案有哪些</li><li>用户在公开社区里最常抱怨什么</li><li>这个问题常见于哪些场景和人群</li><li>现有产品通常忽略了什么</li></ul><p>这一步不能代替真实调研，但很适合帮你快速搭一个问题地图。</p><p>一个很简单的小白输入可以是：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我想做一个帮大学生改简历的工具。</span></span>
<span class="line"><span>你先别帮我想功能，先帮我看看大家在这个问题上最常遇到什么麻烦。</span></span></code></pre></div><p>AI 可能输出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>初步问题地图：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 不知道该写什么经历</span></span>
<span class="line"><span>2. 不知道怎么针对岗位修改</span></span>
<span class="line"><span>3. 改了很多版还是不确定是否够好</span></span>
<span class="line"><span>4. 需要别人帮看，但不方便总麻烦别人</span></span>
<span class="line"><span>5. 因为不确定，所以一直拖着不投</span></span></code></pre></div><p>这种输出的作用不是替你下结论，而是让你更快进入 Discover。</p><h3 id="_11-2-在-define-阶段-让-ai-帮你收敛问题定义" tabindex="-1">11.2 在 Define 阶段，让 AI 帮你收敛问题定义 <a class="header-anchor" href="#_11-2-在-define-阶段-让-ai-帮你收敛问题定义" aria-label="Permalink to “11.2 在 Define 阶段，让 AI 帮你收敛问题定义”">​</a></h3><p>很多人收集了一堆资料之后，最难的是把问题收成一句真正清楚的话。你可以把调研笔记交给 AI，让它帮你压缩成几个候选问题定义：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>下面是我在 Discover 阶段收集到的用户反馈和调研笔记：</span></span>
<span class="line"><span>[贴上内容]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请你帮我做三件事：</span></span>
<span class="line"><span>1. 归纳最常出现的问题模式</span></span>
<span class="line"><span>2. 按问题频率、痛感和可验证性，整理出 3 个值得优先解决的问题</span></span>
<span class="line"><span>3. 把每个问题写成一句具体的问题定义</span></span></code></pre></div><p>这样你会更容易进入 Define，而不是一直停留在“问题好多”的状态里。</p><p>你甚至可以把输入写得非常简单：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我现在收集到的问题有：</span></span>
<span class="line"><span>1. 大家不知道简历写什么</span></span>
<span class="line"><span>2. 大家不知道怎么改</span></span>
<span class="line"><span>3. 大家总觉得没改好，不敢投</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你帮我看看，第一版最适合先解决哪个问题。</span></span></code></pre></div><p>AI 可能输出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>建议优先解决的问题：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>“第一次投递实习的学生，不确定简历是否已经达到可投递水平，因此会反复修改并拖延投递。”</span></span>
<span class="line"><span></span></span>
<span class="line"><span>原因：</span></span>
<span class="line"><span>1. 这个问题更具体</span></span>
<span class="line"><span>2. 它能解释拖延行为</span></span>
<span class="line"><span>3. 更容易设计一个小版本去验证</span></span></code></pre></div><p>这类输出很有用，因为它帮你从一堆模糊问题里收出一个更像 MVP 起点的定义。</p><h3 id="_11-3-在-develop-阶段-用-ai-发散多个方案" tabindex="-1">11.3 在 Develop 阶段，用 AI 发散多个方案 <a class="header-anchor" href="#_11-3-在-develop-阶段-用-ai-发散多个方案" aria-label="Permalink to “11.3 在 Develop 阶段，用 AI 发散多个方案”">​</a></h3><p>很多人一定义完问题，就只盯着脑子里第一个想到的方案。AI 在这一步很适合帮你强制发散：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我已经定义了一个核心问题：[你的问题定义]</span></span>
<span class="line"><span>请你不要直接给我一个最终答案，而是从以下角度各提出 2-3 种解决方向：</span></span>
<span class="line"><span>1. 最轻量的 MVP</span></span>
<span class="line"><span>2. 最适合验证需求的方案</span></span>
<span class="line"><span>3. 最适合提高体验的方案</span></span>
<span class="line"><span>4. 不依赖 AI 的方案</span></span>
<span class="line"><span>5. 依赖 AI 的方案</span></span>
<span class="line"><span>最后请对比每种方案的优点、风险和验证成本。</span></span></code></pre></div><p>这样你就不会太早被单一方案绑住。</p><p>一个简单输入可以是：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我现在的问题定义是：</span></span>
<span class="line"><span>“大学生不确定简历是否已经可以投，所以一直拖着不投。”</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请你帮我想 4 种不同解决方案，不要只给我一种。</span></span></code></pre></div><p>AI 可能输出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>方案 1：简历可投递检查清单</span></span>
<span class="line"><span>方案 2：根据岗位描述做针对性改写</span></span>
<span class="line"><span>方案 3：让用户上传简历后给出风险提示</span></span>
<span class="line"><span>方案 4：提供优秀案例对照，帮助用户判断差距</span></span></code></pre></div><p>这时你就更容易进入“比较方案”，而不是一上来只盯着 AI 改写一个方向。</p><h3 id="_11-4-在-deliver-阶段-用-ai-帮你生成原型文案和测试材料" tabindex="-1">11.4 在 Deliver 阶段，用 AI 帮你生成原型文案和测试材料 <a class="header-anchor" href="#_11-4-在-deliver-阶段-用-ai-帮你生成原型文案和测试材料" aria-label="Permalink to “11.4 在 Deliver 阶段，用 AI 帮你生成原型文案和测试材料”">​</a></h3><p>当你进入 Deliver 阶段，AI 非常适合帮你加快这些工作：</p><ul><li>生成低保真原型里的页面文案</li><li>整理用户测试脚本</li><li>生成可对比的多个版本标题、按钮、说明语</li><li>整理测试后的反馈和问题列表</li></ul><p>比如你可以让 AI 帮你生成一个 20 分钟用户测试脚本，或者帮你把 5 个用户反馈归纳成“继续做 / 修改方向 / 暂停”的判断依据。</p><p>比如一个最小输入可以是：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我做了一个很简单的原型：</span></span>
<span class="line"><span>用户上传简历，系统告诉他哪些地方还不适合投递。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请帮我生成一份 15 分钟的用户测试脚本。</span></span></code></pre></div><p>AI 可能输出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>15 分钟测试脚本：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 先请用户描述最近一次投简历经历</span></span>
<span class="line"><span>2. 让用户独立完成上传简历</span></span>
<span class="line"><span>3. 观察他是否看得懂反馈结果</span></span>
<span class="line"><span>4. 询问：这些提示里哪些最有帮助，哪些让你困惑</span></span>
<span class="line"><span>5. 询问：如果下次投递前，你会不会想再用一次</span></span></code></pre></div><p>这种输出很实用，因为它能帮你从“我做完原型了”走到“我接下来怎么测”。</p><h3 id="_11-5-让-ai-扮演-阶段守门员" tabindex="-1">11.5 让 AI 扮演“阶段守门员” <a class="header-anchor" href="#_11-5-让-ai-扮演-阶段守门员" aria-label="Permalink to “11.5 让 AI 扮演“阶段守门员””">​</a></h3><p>双钻模型最常见的问题，是人会跳阶段。你可以直接让 AI 充当一个守门员，提醒你现在到底在哪一步：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请你扮演产品流程教练。</span></span>
<span class="line"><span>下面是我当前的项目状态：[你的描述]</span></span>
<span class="line"><span>请你判断我现在更像处于 Discover、Define、Develop 还是 Deliver。</span></span>
<span class="line"><span>并告诉我：</span></span>
<span class="line"><span>1. 我是不是过早跳到了下一阶段</span></span>
<span class="line"><span>2. 当前阶段最该补的动作是什么</span></span>
<span class="line"><span>3. 哪些事情现在先别做</span></span></code></pre></div><p>这对新手特别有帮助，因为你很容易在“还没想清楚问题时就开始画原型”。</p><h2 id="📚-assignments" tabindex="-1">📚 Assignments <a class="header-anchor" href="#📚-assignments" aria-label="Permalink to “📚 Assignments”">​</a></h2><p>请你根据上文内容，完成下列作业：</p><ol><li>选一个你最近想做的产品点子，写出它的 Discover、Define、Develop、Deliver 四步草稿</li><li>在 Define 阶段，强迫自己把问题缩成一句具体的话</li><li>在 Develop 阶段，至少列出 3 种不同方案，而不是只盯着第一个想到的做法</li><li>在 Deliver 阶段，写出一个一周内能交付的最小验证版本</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><p>这篇文章主要参考了 Design Council 关于 Double Diamond 的官方资料，适合继续往下看：</p><ul><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/" target="_blank" rel="noreferrer">Design Council: The Double Diamond</a></li><li><a href="https://www.designcouncil.org.uk/our-work/skills-learning/tools-frameworks/framework-for-innovation-design-councils-evolved-double-diamond/" target="_blank" rel="noreferrer">Design Council: Framework for Innovation</a></li><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/history-of-the-double-diamond/" target="_blank" rel="noreferrer">Design Council: History of the Double Diamond</a></li></ul>`,171))])}}});export{u as __pageData,k as default};
